from collections import deque
N=100
masks={}
for name in ['T','B','L','R','UL','UR','LL','LR']:
 cells=[]
 for r in range(10):
  for c in range(10):
   yes={'T':r<5,'B':r>=5,'L':c<5,'R':c>=5,'UL':c<=9-r,'UR':c>=9-r,'LL':c<=r,'LR':c>=r}[name]
   if yes: cells.append(r*10+c)
 masks[name]=sum(1<<i for i in cells)
target=0
for r in range(10):
 for c in range(10):
  f=(c>=9-r) if r<5 else (c<=r)
  if f:target|=1<<(r*10+c)
ALL=(1<<100)-1
# BFS to depth 8, op=(mask,color)
start=0
q=deque([start]); prev={start:None}; pop={}
sol=None
while q:
 s=q.popleft()
 # depth calc
 d=0;z=s
 while prev[z] is not None:d+=1;z=prev[z]
 if d>=8:continue
 for name,m in masks.items():
  for col in [0,1]:
   ns=(s|m) if col else (s&~m&ALL)
   if ns==s or ns in prev:continue
   prev[ns]=s;pop[ns]=(name,col)
   if ns==target:sol=ns;q.clear();break
   q.append(ns)
  if sol is not None:break
 if sol is not None:break
print('visited',len(prev),'sol',sol is not None)
if sol is not None:
 ops=[];z=sol
 while prev[z] is not None:ops.append(pop[z]);z=prev[z]
 print(ops[::-1])
